"""
Streamlit app: upload an image and get the probability of it being AI-generated or real.

Run with:
    streamlit run eval.py

Uses the same setup as main.py:
  - frozen ResNet50 (ImageNet V2 weights) backbone with fc = Identity -> 2048-d features
  - a linear head (nn.Linear(2048, 2)) trained by train_fc() and saved as a state_dict
  - label mapping: 0 -> 'real', 1 -> 'ai'
"""

## This file is AI generated by Claude.

import os
import glob

import torch
import torch.nn as nn
import torchvision.models as models
from torchvision import transforms
from PIL import Image
import streamlit as st

device = torch.device("cpu")

IMAGENET_MEAN = [0.485, 0.456, 0.406]
IMAGENET_STD = [0.229, 0.224, 0.225]
CLASS_NAMES = ["real", "ai"]  # 0 -> real, 1 -> ai (same as main.py)

# Same deterministic transform as val_transform in main.py
val_transform = transforms.Compose([
    transforms.Resize(224),
    transforms.ToTensor(),
    transforms.Normalize(IMAGENET_MEAN, IMAGENET_STD),
])


# ---------------------------------------------------------------------------
# Model loading (cached so the slow backbone loads only once per session)
# ---------------------------------------------------------------------------

@st.cache_resource(show_spinner="Loading ResNet50 backbone...")
def load_backbone():
    backbone = models.resnet50(weights=models.ResNet50_Weights.IMAGENET1K_V2)
    backbone.fc = nn.Identity()
    for p in backbone.parameters():
        p.requires_grad = False
    backbone = backbone.to(device).to(memory_format=torch.channels_last)
    backbone.eval()
    return backbone


@st.cache_resource(show_spinner="Loading checkpoint...")
def load_head(checkpoint_path, mtime):
    # mtime is part of the cache key so a re-saved checkpoint gets reloaded
    state = torch.load(checkpoint_path, map_location=device)
    # support either a raw state_dict or a dict wrapping one
    if isinstance(state, dict) and "state_dict" in state:
        state = state["state_dict"]
    in_features = state["weight"].shape[1]
    clf = nn.Linear(in_features, 2)
    clf.load_state_dict(state)
    clf.eval()
    return clf


@torch.inference_mode()
def predict(img, backbone, clf):
    x = val_transform(img.convert("RGB")).unsqueeze(0)
    x = x.to(device).contiguous(memory_format=torch.channels_last)
    feats = backbone(x)
    probs = torch.softmax(clf(feats), dim=1)[0]
    return {"real": probs[0].item(), "ai": probs[1].item()}


def find_checkpoints(folder):
    if not os.path.isdir(folder):
        return []
    return sorted(
        glob.glob(os.path.join(folder, "*.pt")) + glob.glob(os.path.join(folder, "*.pth")),
        key=os.path.getmtime,
        reverse=True,
    )


# ---------------------------------------------------------------------------
# UI
# ---------------------------------------------------------------------------

st.set_page_config(page_title="AI vs Real Image Detector", page_icon="🔍", layout="centered")
st.title("🔍 AI vs Real Image Detector")
st.caption("ResNet50 features + linear head. Upload an image to get the probability it is AI-generated.")

with st.sidebar:
    st.header("Checkpoint")
    ckpt_dir = st.text_input("Checkpoint folder", value=".")
    found = [c for c in find_checkpoints(ckpt_dir) if os.path.basename(c) != "features.pt"]

    selected = None
    if found:
        selected = st.selectbox(
            "Select checkpoint",
            found,
            format_func=lambda p: os.path.basename(p),
            help="Lists .pt / .pth files in the folder (newest first). features.pt is excluded.",
        )
    else:
        st.warning("No checkpoints found in that folder.")

    custom = st.text_input("...or enter a checkpoint path manually", value="")
    if custom.strip():
        selected = custom.strip()

    if st.button("Rescan folder"):
        st.rerun()

    st.divider()
    threshold = st.slider("Decision threshold (P[ai])", 0.05, 0.95, 0.5, 0.05)

if selected is None or not os.path.isfile(selected):
    st.info("Pick a valid checkpoint in the sidebar (e.g. `fc_best.pt` produced by main.py).")
    st.stop()

try:
    backbone = load_backbone()
    clf = load_head(selected, os.path.getmtime(selected))
except Exception as e:
    st.error(f"Failed to load checkpoint `{selected}`: {e}")
    st.stop()

st.sidebar.success(f"Loaded: {os.path.basename(selected)}")

uploaded = st.file_uploader("Upload an image", type=["jpg", "jpeg", "png", "webp", "bmp"])

if uploaded is not None:
    img = Image.open(uploaded)
    st.image(img, caption=uploaded.name, use_container_width=True)

    with st.spinner("Running model..."):
        result = predict(img, backbone, clf)

    p_ai, p_real = result["ai"], result["real"]
    verdict = "AI-generated" if p_ai >= threshold else "Real"

    if verdict == "AI-generated":
        st.error(f"Prediction: **{verdict}**")
    else:
        st.success(f"Prediction: **{verdict}**")

    c1, c2 = st.columns(2)
    c1.metric("P(real)", f"{p_real * 100:.2f}%")
    c2.metric("P(AI)", f"{p_ai * 100:.2f}%")

    st.progress(min(max(p_ai, 0.0), 1.0), text=f"AI probability: {p_ai * 100:.1f}%")